<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CanteenIssueController extends Controller{
private function issue(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('canteen_manager')||$r->user()->canDo('canteen.issue'),403);}
public function terminal(Request $r){$this->issue($r);$recent=DB::table('meal_issues as i')->join('students as s','s.id','=','i.student_id')->leftJoin('meal_categories as c','c.id','=','i.meal_category_id')->where('i.issue_date',date('Y-m-d'))->select('i.*','s.last_name','s.first_name','c.name as category_name')->orderByDesc('i.issued_at')->limit(30)->get();return view('canteen.terminal',compact('recent'));}
public function scan(Request $r){$this->issue($r);$d=$r->validate(['token'=>'required|string|max:100','meal_type'=>'required|in:breakfast,lunch,snack,dinner']);$pass=DB::table('student_meal_passes')->where(['token'=>$d['token'],'status'=>'active'])->first();if(!$pass)return response()->json(['ok'=>false,'message'=>'Пропуск не найден или заблокирован'],422);$student=DB::table('students')->find($pass->student_id);if(!$student||$student->status!=='active')return response()->json(['ok'=>false,'message'=>'Студент неактивен'],422);$today=date('Y-m-d');if(DB::table('meal_issues')->where(['issue_date'=>$today,'meal_type'=>$d['meal_type'],'student_id'=>$student->id])->exists())return response()->json(['ok'=>false,'message'=>'Питание этого типа сегодня уже выдано','student'=>$student->last_name.' '.$student->first_name],409);$assignment=DB::table('student_meal_assignments as a')->join('meal_categories as c','c.id','=','a.meal_category_id')->where('a.student_id',$student->id)->where('a.valid_from','<=',$today)->where(function($q)use($today){$q->whereNull('a.valid_to')->orWhere('a.valid_to','>=',$today);})->where('c.active',1)->select('a.*','c.name as category_name','c.daily_limit')->orderByDesc('a.valid_from')->first();if(!$assignment)return response()->json(['ok'=>false,'message'=>'На сегодня питание студенту не назначено','student'=>$student->last_name.' '.$student->first_name],422);$menu=DB::table('meal_menus')->where(['menu_date'=>$today,'meal_type'=>$d['meal_type'],'active'=>1])->orderBy('id')->first();$amount=$menu?min((float)$menu->price,(float)($assignment->daily_limit??$menu->price)):0;DB::table('meal_issues')->insert(['issue_date'=>$today,'meal_type'=>$d['meal_type'],'student_id'=>$student->id,'meal_category_id'=>$assignment->meal_category_id,'meal_menu_id'=>$menu->id??null,'student_meal_pass_id'=>$pass->id,'amount'=>$amount,'issued_at'=>now(),'issued_by'=>$r->user()->id,'source'=>'qr','created_at'=>now(),'updated_at'=>now()]);return response()->json(['ok'=>true,'student'=>$student->last_name.' '.$student->first_name,'category'=>$assignment->category_name,'meal'=>$menu->title??$d['meal_type']]);}
public function report(Request $r){$this->issue($r);$from=$r->get('from',date('Y-m-01'));$to=$r->get('to',date('Y-m-d'));$rows=DB::table('meal_issues as i')->join('students as s','s.id','=','i.student_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->leftJoin('meal_categories as c','c.id','=','i.meal_category_id')->whereBetween('i.issue_date',[$from,$to])->select('i.issue_date','i.meal_type','g.name as group_name','c.name as category_name',DB::raw('COUNT(*) portions'),DB::raw('SUM(i.amount) amount'))->groupBy('i.issue_date','i.meal_type','g.name','c.name')->orderByDesc('i.issue_date')->get();$total=DB::table('meal_issues')->whereBetween('issue_date',[$from,$to])->selectRaw('COUNT(*) portions, COALESCE(SUM(amount),0) amount')->first();return view('canteen.report',compact('rows','total','from','to'));}
}